const ENGLISH_TOPIC_LINE: Record<
  TutorSettings['explanationLanguage'],
  (title: string) => string
> = {
  ...TOPIC_LINE,
  ko: (title) => `오늘의 주제: ${title}.`,
};

export function voiceTutorGreeting(
  settings: TutorSettings,
  plan: TutorPlan,
  /** 고른 회화 주제 제목 (수업 언어). ko 수업은 plan.lessonGoal 에 이미 들어 있다 */
  topicTitle?: string,
): string {
  const language = settings.explanationLanguage;
  if (settings.targetLanguage === 'en') {
    const byPersonality =
      ENGLISH_TUTOR_GREETINGS[language][settings.personality] ??
      ENGLISH_TUTOR_GREETINGS[language].friendly;
    const greeting =
      byPersonality[settings.speechStyle] ?? byPersonality.polite;
    return topicTitle
      ? withTopic(greeting, ENGLISH_TOPIC_LINE[language](topicTitle))
      : greeting;
  }
  if (language !== 'ko') {
    const byPersonality =
      FOREIGN_GREETINGS[language][settings.personality] ??
      FOREIGN_GREETINGS[language].friendly;
    const greeting =
      byPersonality[settings.speechStyle] ?? byPersonality.polite;
    return topicTitle
      ? withTopic(greeting, TOPIC_LINE[language](topicTitle))
      : greeting;
  }
  const goal = plan.lessonGoal.slice(0, 120);
  if (settings.speechStyle === 'polite') {
    switch (settings.personality) {
      case 'close_friend':
        return `오셨어요! 오늘은 ${goal} 연습해 볼게요. 먼저 편하게 한마디 해 보실래요?`;
      case 'savage':
        return `오셨네요. 오늘은 ${goal} 연습이에요. 어떻게 말하는지 한번 볼까요?`;
      case 'chaotic_savage':
        return `오셨네요! 바로 시작해 볼까요? 오늘은 ${goal} 연습이에요. 자, 첫 문장부터 저를 놀라게 해 보세요!`;
      default:
        return `안녕하세요! 오늘은 ${goal} 연습해 볼게요. 먼저 편하게 한마디 해 보시겠어요?`;
    }
  }
  switch (settings.personality) {
    case 'close_friend':
      return `왔네! 오늘은 ${goal} 연습하자. 먼저 편하게 한마디 해 봐.`;
    case 'savage':
      return `왔냐? 오늘은 ${goal} 연습이다. 네가 할 수 있는 표현부터 보여줘.`;
    case 'chaotic_savage':
      return `좋아, 바로 시작하자! 오늘은 ${goal} 연습이야. 자, 첫 문장부터 나를 놀라게 해 봐!`;
    default:
      return `안녕! 오늘은 ${goal} 연습해 보자. 먼저 편하게 한마디 해 볼래?`;
  }
}
